const fundingRows=projectFundingSummaries(w,scope,to).map(f=>{const source=f.sourceType==='project'?pname(f.sourceProject||''):f.sourceType==='external'?'جهة خارجية':'المالك / ماله الشخصي';return {...f,source};});
const fundingByMonth=projectFundings.filter(f=>String(f.data.date).startsWith(month));const ownerYearKeys=Array.from(new Set([...fiscalYears.map(x=>Number(String(x.data.start).slice(0,4))),Number(fiscalYear.start.slice(0,4))])).sort((a,b)=>a-b);const ownerYears=ownerYearKeys.map(y=>annualOwnerReport(w,y));const ownerAnnual=annualOwnerReport(w,Number(fiscalYear.start.slice(0,4)));
